public class Mutation
{
    private readonly IUserService _userService;
    private readonly IConfiguration _config;

    public Mutation(IUserService userService, IConfiguration config)
    {
        _userService = userService;
        _config = config;
    }

    [Mutation]
    public async Task<string> Login(string email, string password)
    {
        var user = await _userService.ValidateAsync(email, password);
        if (user == null) throw new GraphQLException("Invalid credentials.");

        var token = new JwtSecurityToken(
            issuer: _config["Jwt:Issuer"],
            audience: _config["Jwt:Audience"],
            claims: new[] { new Claim(ClaimTypes.Name, user.Email) },
            expires: DateTime.UtcNow.AddHours(2),
            signingCredentials: new SigningCredentials(
                new SymmetricSecurityKey(
                    Encoding.UTF8.GetBytes(_config["Jwt:Key"])),
                SecurityAlgorithms.HmacSha256));

        return new JwtSecurityTokenHandler().WriteToken(token);
    }
}

